    30	// Note: This has to be initialized inside a function and not at the top level of the file, because Intl is polyfilled,
    31	// and if React Native executes this code upon import, then the polyfill will not be available yet and it will barf
    32	let CONJUNCTION_LIST_FORMATS_FOR_LOCALES: Record<string, Intl.ListFormat>;
    33	function init() {
    34	    CONJUNCTION_LIST_FORMATS_FOR_LOCALES = Object.values(CONST.LOCALES).reduce((memo: Record<string, Intl.ListFormat>, locale) => {
    35	        // This is not a supported locale, so we'll use ES_ES instead
    36	        if (locale === CONST.LOCALES.ES_ES_ONFIDO) {
    37	            // eslint-disable-next-line no-param-reassign
    38	            memo[locale] = new Intl.ListFormat(CONST.LOCALES.ES_ES, {style: 'long', type: 'conjunction'});
    39	            return memo;
    40	        }
    41	
    42	        // eslint-disable-next-line no-param-reassign
    43	        memo[locale] = new Intl.ListFormat(locale, {style: 'long', type: 'conjunction'});
    44	        return memo;
    45	    }, {});
    46	}
    47	
    48	/**
    49	 * Map to store translated values for each locale.
    50	 * This is used to avoid translating the same phrase multiple times.
    51	 *
    52	 * The data is stored in the following format:
    53	 *
    54	 * {
    55	 *  "en": {
    56	 *   "name": "Name",
    57	 * }
    58	 *
    59	 * Note: We are not storing any translated values for phrases with variables,
    60	 * as they have higher chance of being unique, so we'll end up wasting space
    61	 * in our cache.
    62	 */
    63	const translationCache = new Map<ValueOf<typeof CONST.LOCALES>, Map<TranslationPaths, string>>(
    64	    Object.values(CONST.LOCALES).reduce((cache, locale) => {
    65	        cache.push([locale, new Map<TranslationPaths, string>()]);
    66	        return cache;
    67	    }, [] as Array<[ValueOf<typeof CONST.LOCALES>, Map<TranslationPaths, string>]>),
    68	);
    69	
    70	/**
    71	 * Helper function to get the translated string for given
    72	 * locale and phrase. This function is used to avoid
    73	 * duplicate code in getTranslatedPhrase and translate functions.
    74	 *
    75	 * This function first checks if the phrase is already translated
    76	 * and in the cache, it returns the translated value from the cache.
    77	 *
    78	 * If the phrase is not translated, it checks if the phrase is
    79	 * available in the given locale. If it is, it translates the
    80	 * phrase and stores the translated value in the cache and returns
    81	 * the translated value.
    82	 */
    83	function getTranslatedPhrase<TKey extends TranslationPaths>(
    84	    language: 'en' | 'es' | 'es-ES',
    85	    phraseKey: TKey,
    86	    fallbackLanguage: 'en' | 'es' | null,
    87	    ...parameters: TranslationParameters<TKey>
    88	): string | null {
    89	    // Get the cache for the above locale
    90	    const cacheForLocale = translationCache.get(language);
    91	
    92	    // Directly access and assign the translated value from the cache, instead of
    93	    // going through map.has() and map.get() to avoid multiple lookups.
    94	    const valueFromCache = cacheForLocale?.get(phraseKey);
    95	
    96	    // If the phrase is already translated, return the translated value
    97	    if (valueFromCache) {
    98	        return valueFromCache;
    99	    }
   100	
   101	    const translatedPhrase = translations?.[language]?.[phraseKey];
   102	
   103	    if (translatedPhrase) {
   104	        if (typeof translatedPhrase === 'function') {
   105	            /**
   106	             * If the result of `translatedPhrase` is an object, check if it contains the 'count' parameter
   107	             * to handle pluralization logic.
   108	             * Alternatively, before evaluating the translated result, we can check if the 'count' parameter
   109	             * exists in the passed parameters.
   110	             */
   111	            const translateFunction = translatedPhrase as unknown as (...parameters: TranslationParameters<TKey>) => string | PluralForm;
   112	            const translateResult = translateFunction(...parameters);
   113	
   114	            if (typeof translateResult === 'string') {
   115	                return translateResult;
   116	            }
   117	
   118	            const phraseObject = parameters[0] as {count?: number};
   119	            if (typeof phraseObject?.count !== 'number') {
   120	                throw new Error(`Invalid plural form for '${phraseKey}'`);
   121	            }
   122	
   123	            const pluralRule = new Intl.PluralRules(language).select(phraseObject.count);
   124	
   125	            const pluralResult = translateResult[pluralRule];
   126	            if (pluralResult) {
   127	                if (typeof pluralResult === 'string') {
   128	                    return pluralResult;
   129	                }
   130	
   131	                return pluralResult(phraseObject.count);
   132	            }
   133	
   134	            if (typeof translateResult.other === 'string') {
   135	                return translateResult.other;
   136	            }
   137	
   138	            return translateResult.other(phraseObject.count);
   139	        }
   140	
   141	        // We set the translated value in the cache only for the phrases without parameters.
   142	        cacheForLocale?.set(phraseKey, translatedPhrase);
   143	        return translatedPhrase;
   144	    }
   145	
   146	    if (!fallbackLanguage) {
   147	        return null;
   148	    }
   149	
   150	    // Phrase is not found in full locale, search it in fallback language e.g. es
   151	    const fallbackTranslatedPhrase = getTranslatedPhrase(fallbackLanguage, phraseKey, null, ...parameters);
   152	
   153	    if (fallbackTranslatedPhrase) {
   154	        return fallbackTranslatedPhrase;
   155	    }
   156	
   157	    if (fallbackLanguage !== CONST.LOCALES.DEFAULT) {
   158	        Log.alert(`${phraseKey} was not found in the ${fallbackLanguage} locale`);
   159	    }
   160	
   161	    // Phrase is not translated, search it in default language (en)
   162	    return getTranslatedPhrase(CONST.LOCALES.DEFAULT, phraseKey, null, ...parameters);
   163	}
