   165	/**
   166	 * Return translated string for given locale and phrase
   167	 *
   168	 * @param [desiredLanguage] eg 'en', 'es-ES'
   169	 * @param [parameters] Parameters to supply if the phrase is a template literal.
   170	 */
   171	function translate<TPath extends TranslationPaths>(desiredLanguage: 'en' | 'es' | 'es-ES' | 'es_ES', path: TPath, ...parameters: TranslationParameters<TPath>): string {
   172	    // Search phrase in full locale e.g. es-ES
   173	    const language = desiredLanguage === CONST.LOCALES.ES_ES_ONFIDO ? CONST.LOCALES.ES_ES : desiredLanguage;
   174	    // Phrase is not found in full locale, search it in fallback language e.g. es
   175	    const languageAbbreviation = desiredLanguage.substring(0, 2) as 'en' | 'es';
   176	
   177	    const translatedPhrase = getTranslatedPhrase(language, path, languageAbbreviation, ...parameters);
   178	    if (translatedPhrase !== null && translatedPhrase !== undefined) {
   179	        return translatedPhrase;
   180	    }
   181	
   182	    // Phrase is not found in default language, on production and staging log an alert to server
   183	    // on development throw an error
   184	    if (Config.IS_IN_PRODUCTION || Config.IS_IN_STAGING) {
   185	        const phraseString = Array.isArray(path) ? path.join('.') : path;
   186	        Log.alert(`${phraseString} was not found in the en locale`);
   187	        if (userEmail.includes(CONST.EMAIL.EXPENSIFY_EMAIL_DOMAIN)) {
   188	            return CONST.MISSING_TRANSLATION;
   189	        }
   190	        return phraseString;
   191	    }
   192	    throw new Error(`${path} was not found in the default language`);
   193	}
   194	
   195	/**
   196	 * Uses the locale in this file updated by the Onyx subscriber.
   197	 */
   198	function translateLocal<TPath extends TranslationPaths>(phrase: TPath, ...parameters: TranslationParameters<TPath>) {
   199	    return translate(BaseLocaleListener.getPreferredLocale(), phrase, ...parameters);
   200	}
   201	
   202	function getPreferredListFormat(): Intl.ListFormat {
   203	    if (!CONJUNCTION_LIST_FORMATS_FOR_LOCALES) {
   204	        init();
   205	    }
   206	
   207	    return CONJUNCTION_LIST_FORMATS_FOR_LOCALES[BaseLocaleListener.getPreferredLocale()];
   208	}
   209	
   210	/**
   211	 * Format an array into a string with comma and "and" ("a dog, a cat and a chicken")
   212	 */
   213	function formatList(components: string[]) {
   214	    const listFormat = getPreferredListFormat();
   215	    return listFormat.format(components);
   216	}
   217	
   218	function formatMessageElementList<E extends MessageElementBase>(elements: readonly E[]): ReadonlyArray<E | MessageTextElement> {
   219	    const listFormat = getPreferredListFormat();
   220	    const parts = listFormat.formatToParts(elements.map((e) => e.content));
   221	    const resultElements: Array<E | MessageTextElement> = [];
   222	
   223	    let nextElementIndex = 0;
   224	    for (const part of parts) {
   225	        if (part.type === 'element') {
   226	            /**
   227	             * The standard guarantees that all input elements will be present in the constructed parts, each exactly
   228	             * once, and without any modifications: https://tc39.es/ecma402/#sec-createpartsfromlist
   229	             */
   230	            const element = elements[nextElementIndex++];
   231	
   232	            resultElements.push(element);
   233	        } else {
   234	            const literalElement: MessageTextElement = {
   235	                kind: 'text',
   236	                content: part.value,
   237	            };
   238	
   239	            resultElements.push(literalElement);
   240	        }
   241	    }
   242	
   243	    return resultElements;
   244	}
   245	
   246	/**
   247	 * Returns the user device's preferred language.
   248	 */
   249	function getDevicePreferredLocale(): Locale {
   250	    return RNLocalize.findBestAvailableLanguage([CONST.LOCALES.EN, CONST.LOCALES.ES])?.languageTag ?? CONST.LOCALES.DEFAULT;
   251	}
   252	
   253	export {translate, translateLocal, formatList, formatMessageElementList, getDevicePreferredLocale};
